      </div>
      <div class="cm-tall">${jsonBlock(d)}</div>`, i === s.snapIdx);
  }).join('');
}

function renderFilesTab(s, panel) {
  const files = s.manifest.files || [];
  if (!files.length) {
    panel.innerHTML = layer('Companion files', 'none', '<p class="hint">Subagent transcripts and other session files land here when exported.</p>', true);
    return;
  }
  panel.innerHTML = layer('Companion files', `${files.length}`, files.map((f) =>
    `<div style="font-family:var(--mono);font-size:12.5px;padding:2px 0"><a href="/api/sessions/${esc(s.id)}/files/${encodeURIComponent(f)}" target="_blank" rel="noopener">${esc(f)}</a></div>`).join(''), true);
}

