    </button>`;
  }).join('')}</div>`;

  const sn = s.snapshots[s.snapIdx];
  const d = sn.data;
  const sysSecs = d.systemPrompt || [];
  const tools = d.tools || [];
  const rules = d.rules || [];

  const body = [];
  body.push(layer(`Snapshot ${s.snapIdx + 1}`, esc(d.exportedAt || sn.name), `
