    </div>`, true));

  body.push(layer('System prompt — as transcribed', `${sysSecs.length} sections`,
    sysSecs.length
      ? sysSecs.map((sec) => `<details class="msg"><summary><span class="role" style="color:var(--k-attach)">§</span><span class="prev">${esc(sec.title)}</span></summary><div class="body"><pre class="block">${esc(sec.content)}</pre></div></details>`).join('')
      : '<p class="hint">No system-prompt sections in this snapshot.</p>'));

  if (tools.length) {
    body.push(layer('Tool definitions — as transcribed', `${tools.length} tools`,
      tools.map((t) => `<details class="msg"><summary><span class="role" style="color:var(--k-tool)">⚒</span><span class="prev">${esc(t.name)} — ${esc((t.description || '').slice(0, 90))}</span></summary><div class="body"><pre class="block">${esc(t.description || '')}</pre><div class="blk-tag" style="margin-top:8px">parameter schema</div>${jsonBlock(t.schema ?? t.parameters ?? {})}</div></details>`).join('')));
  }
  if (rules.length) {
    body.push(layer('Rules & memory files', `${rules.length} files`,
      rules.map((f) => `<details class="msg"><summary><span class="role" style="color:var(--k-user)">✎</span><span class="prev">${esc(f.path)}</span></summary><div class="body"><pre class="block">${esc(f.content)}</pre></div></details>`).join('')));
  }

  body.push(layer('Raw snapshot JSON', esc(sn.name || ''),
    `<div class="cm-tall">${jsonBlock(d)}</div>`));

  panel.innerHTML = strip + body.join('');
  panel.querySelectorAll('.snap-chip').forEach((chip) =>
    chip.addEventListener('click', () => { s.snapIdx = +chip.dataset.i; renderPanel(s); }));
}

