const otherIdx = report1.selectedChip === 0 ? 1 : 0;
doc.querySelectorAll('.snap-chip')[otherIdx].click();
await new Promise((r) => setTimeout(r, 300));
const chips2 = [...doc.querySelectorAll('.snap-chip')];
const report2 = {
  selectedChip: chips2.findIndex((c) => c.classList.contains('on')),
  headline: doc.querySelector('#panel .layer summary .eyebrow')?.textContent,
  snapshotLayerCount: [...doc.querySelectorAll('#panel .layer summary .eyebrow')].filter((e) => /^Snapshot \d+$/.test(e.textContent)).length,
  rawJsonCount: [...doc.querySelectorAll('#panel .layer summary .eyebrow')].filter((e) => e.textContent === 'Raw snapshot JSON').length,
  errors,
};
console.log('after chip click:', JSON.stringify(report2, null, 2));

const ok = chips.length === 2 && report1.selectedChip >= 0 && report1.rawJsonCollapsed === true
  && report2.selectedChip === otherIdx && report2.snapshotLayerCount === 1 && report2.rawJsonCount === 1 && !errors.length;
console.log(ok ? 'SNAPSHOT TAB OK' : 'SNAPSHOT TAB FAILED');
process.exit(ok ? 0 : 1);
